# These addresses fall in data sections (OBJECT), not code. Let me check what section they're in
aarch64-linux-gnu-readelf -s "/tmp/libmonosgen-2.0.so.debug" 2>/dev/null | awk '$2 != "" && strtonum("0x"$2) > 0' | sort -k2 | awk '
BEGIN { addr1="00000000002f4b20"; addr2="00000000002f4c84" }
{
  if ($2 <= addr1) prev1 = $0
  if ($2 <= addr2) prev2 = $0
  if (found1 == 0 && $2 > addr1) { print "0x2f4b20 nearest: " prev1; found1=1 }
  if (found2 == 0 && $2 > addr2) { print "0x2f4c84 nearest: " prev2; found2=1 }
}'

